BEGIN;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.financieras_competidoras_versiones AS version
    WHERE version.financiera_id IN (
      'b0400000-0000-4000-8000-000000000001'::UUID,
      'b0400000-0000-4000-8000-000000000002'::UUID,
      'b0400000-0000-4000-8000-000000000003'::UUID,
      'b0400000-0000-4000-8000-000000000004'::UUID,
      'b0400000-0000-4000-8000-000000000005'::UUID,
      'b0400000-0000-4000-8000-000000000006'::UUID,
      'b0400000-0000-4000-8000-000000000007'::UUID,
      'b0400000-0000-4000-8000-000000000008'::UUID,
      'b0400000-0000-4000-8000-000000000009'::UUID,
      'b0400000-0000-4000-8000-000000000010'::UUID,
      'b0400000-0000-4000-8000-000000000011'::UUID,
      'b0400000-0000-4000-8000-000000000012'::UUID,
      'b0400000-0000-4000-8000-000000000013'::UUID
    )
  ) THEN
    RAISE EXCEPTION 'No se puede revertir el catálogo base porque ya existe historial de clasificación';
  END IF;
END
$$;

DELETE FROM public.financieras_competidoras
WHERE id IN (
  'b0400000-0000-4000-8000-000000000001'::UUID,
  'b0400000-0000-4000-8000-000000000002'::UUID,
  'b0400000-0000-4000-8000-000000000003'::UUID,
  'b0400000-0000-4000-8000-000000000004'::UUID,
  'b0400000-0000-4000-8000-000000000005'::UUID,
  'b0400000-0000-4000-8000-000000000006'::UUID,
  'b0400000-0000-4000-8000-000000000007'::UUID,
  'b0400000-0000-4000-8000-000000000008'::UUID,
  'b0400000-0000-4000-8000-000000000009'::UUID,
  'b0400000-0000-4000-8000-000000000010'::UUID,
  'b0400000-0000-4000-8000-000000000011'::UUID,
  'b0400000-0000-4000-8000-000000000012'::UUID,
  'b0400000-0000-4000-8000-000000000013'::UUID
);

ALTER TABLE public.financieras_competidoras
  DROP COLUMN catalogo_base;

COMMIT;
